'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelRpc} from '@/lib/pilot';
import {useClientReady} from '@/lib/client-ready';
import {GuestFields} from '@/components/guest-fields';
import {GuestSearchPanel} from '@/components/guest-records-panel';
import {useGuestRequest,GuestRecovery} from '@/components/guest-request';
import {billingFromGuest,guestFormData,type BillingData,type GuestData,type GuestProfile,type StayGuest,type GuestReceipt,type GuestSummary} from '@/lib/guests';
type Props={autoSave?:boolean;initialBilling?:BillingData;initialContact?:Partial<GuestData>;onSaved?:()=>Promise<void>;actor:string;tenant:string;property:string;reservation:string;onBusyChange:(busy:boolean)=>void};
export function ReservationGuestPanel(props:Props){return useClientReady()?<StayGuestForm {...props}/>:<p>Loading stay contact details…</p>}
function StayGuestForm({actor,tenant,property,reservation,onBusyChange,initialContact,initialBilling,autoSave=false,onSaved}:Props){
 const [sameGuest,setSameGuest]=useState(!initialBilling);const autoStarted=useRef(false);
 const [data,setData]=useState<StayGuest|null>(null),[mode,setMode]=useState<'keep'|'local'|'profile'>('local'),[profile,setProfile]=useState<GuestProfile|null>(null),[readError,setReadError]=useState(''),[formError,setFormError]=useState(''),[notice,setNotice]=useState(''),[revision,setRevision]=useState(0),[profileLoading,setProfileLoading]=useState(false);const alive=useRef(true),sequence=useRef(0),profileSequence=useRef(0);
 const request=useGuestRequest({storageKey:'iratepilot-pms-pending-stay-guest:'+actor+':'+tenant+':'+property+':'+reservation,action:'save_reservation_guest',tenant,property,onBusyChange});
 async function refresh(){const seq=++sequence.current;setData(null);try{const result=await hotelRpc<StayGuest>('reservation_guest',{p_tenant:tenant,p_property:property,p_reservation:reservation});if(alive.current&&sequence.current===seq){setData(result);setMode(result.recorded?'keep':'local');setSameGuest(!initialBilling&&!Object.values(result.billing_party??{}).some(Boolean));setProfile(null);setReadError('');setRevision(v=>v+1)}}catch(e){if(alive.current&&sequence.current===seq)setReadError(e instanceof Error?e.message:'Unable to load stay contact details.')}}
 useEffect(()=>{alive.current=true;const seq=++sequence.current;hotelRpc<StayGuest>('reservation_guest',{p_tenant:tenant,p_property:property,p_reservation:reservation}).then(result=>{if(alive.current&&sequence.current===seq){setData(result);setMode(result.recorded?'keep':'local');setSameGuest(!initialBilling&&!Object.values(result.billing_party??{}).some(Boolean));setReadError('')}}).catch(e=>{if(alive.current&&sequence.current===seq)setReadError(e instanceof Error?e.message:'Unable to load stay contact details.')});return()=>{alive.current=false}},[tenant,property,reservation,initialBilling]);
 async function choose(guest:GuestSummary){const seq=++profileSequence.current;setProfileLoading(true);setProfile(null);setFormError('');try{const result=await hotelRpc<GuestProfile>('guest_profile',{p_tenant:tenant,p_property:property,p_guest:guest.id});if(alive.current&&seq===profileSequence.current)setProfile(result)}catch(e){if(alive.current&&seq===profileSequence.current)setFormError(e instanceof Error?e.message:'Unable to load profile.')}finally{if(alive.current&&seq===profileSequence.current)setProfileLoading(false)}}
 async function saved(_result:GuestReceipt){setNotice('Stay contact and billing details saved.');await refresh();await onSaved?.()}
 useEffect(()=>{
  if(!autoSave||!initialContact||!data||data.recorded||autoStarted.current||request.busy||request.marker||request.blocked)return;
  autoStarted.current=true;
  void request.save(reservation,data.version,{p_reservation:reservation,p_expected_version:data.version,p_guest:null,p_guest_expected_version:null,p_contact:initialContact,p_billing_party:initialBilling??billingFromGuest(initialContact),p_keep_existing_contact:false},saved,()=>{void refresh()});
 });
 return <>{(request.error||readError||formError)&&<div className="pilot-error" role="alert">{request.error||readError||formError}</div>}{(request.notice||notice)&&<output className="pilot-notice">{request.notice||notice}</output>}{request.marker&&request.resuming&&<button className="secondary" disabled={request.busy} onClick={()=>void request.check(saved)}>Check saved guest request again</button>}{request.marker&&!request.resuming?<GuestRecovery busy={request.busy} onCheck={()=>void request.check(saved)}/>:!data?<><p>Load the current stay details before editing.</p><button className="secondary" onClick={()=>void refresh()}>Reload stay details</button></>:<><div className="section-top"><div><h3>{data.reservation_name??'Reservation'}</h3><p>{data.recorded?'Recorded stay contact':'No stay contact saved yet'}</p></div><button className="text-button" disabled={request.busy||!!request.marker} onClick={()=>void refresh()}>Refresh stay details</button></div>{data.linked_profile_changed&&<p className="pilot-notice">The linked profile has changed. This stay keeps its saved copy. Choose “Copy a profile” only if you want to replace that contact information.</p>}<label className="field">Stay contact source<select value={mode} disabled={request.busy||request.blocked} onChange={e=>{setMode(e.target.value as 'keep'|'local'|'profile');setProfile(null)}}>{data.recorded&&<option value="keep">Keep saved contact and profile link</option>}<option value="local">Enter independent stay contact</option><option value="profile">Copy a profile into this stay</option></select></label>{mode==='profile'&&<GuestSearchPanel key={tenant+'/'+property} tenant={tenant} property={property} disabled={request.busy||profileLoading} onSelect={guest=>void choose(guest)} selectLabel="Review this profile"/>}<form autoComplete="off" key={data.version+'/'+revision} onSubmit={e=>{e.preventDefault();setFormError('');setNotice('');const f=new FormData(e.currentTarget);try{if(mode==='profile'&&!profile)throw Error('Choose and review a guest profile first.');const version=data.version;void request.save(reservation,version,{p_reservation:reservation,p_expected_version:version,p_guest:mode==='profile'?profile!.id:null,p_guest_expected_version:mode==='profile'?profile!.version:null,p_contact:mode==='local'?guestFormData(f,'contact_'):null,p_billing_party:sameGuest?billingFromGuest(mode==='local'?guestFormData(f,'contact_') as GuestData:mode==='profile'?profile!.data:data.contact):guestFormData(f,'billing_',true),p_keep_existing_contact:mode==='keep'},saved,()=>{void refresh()})}catch(e){setFormError(e instanceof Error?e.message:'Review stay details.')}}}><fieldset className="pilot-guest-group"><legend>Guest contact for this stay</legend>{mode==='profile'&&!profile?<p>{profileLoading?'Loading selected profile…':'Choose a profile above to review the copy.'}</p>:<><GuestFields key={mode+'/'+(profile?.id??data.version)} prefix="contact_" data={mode==='profile'?profile!.data:!data.recorded&&initialContact?initialContact:data.contact} disabled={request.busy||request.blocked||mode!=='local'}/>{mode==='local'&&data.guest_id&&<p>Saving independent contact details removes this stay’s profile link. The reusable profile stays unchanged.</p>}{mode==='profile'&&<label className="pilot-check"><input type="checkbox" required disabled={request.busy}/>I reviewed this profile and want to copy it into this stay.</label>}</>}</fieldset><fieldset className="pilot-guest-group"><legend>Bill-to details</legend><label className="pilot-check"><input type="checkbox" checked={sameGuest} disabled={request.busy||request.blocked} onChange={e=>setSameGuest(e.target.checked)}/>Same as guest</label>{sameGuest?<p>Uses the guest’s name and contact address. ID and passport details are excluded.</p>:<><p>Bill another person or company.</p><GuestFields prefix="billing_" data={initialBilling??data.billing_party} billing disabled={request.busy||request.blocked}/></>}</fieldset><button className="primary" disabled={request.busy||request.blocked||profileLoading||mode==='profile'&&!profile}>Save stay contact &amp; billing</button></form></>}</>;
}
